// Pure functions over the insights rows: the writes (what one request adds) and every aggregate the admin shows.
// The memory store runs these directly. The Supabase store runs the SQL twins in supabase/migrations/0003_insights.sql;
// supabase/tests/insights_parity.sql (generated by src/server/insights/__tests__/parity.test.ts) proves both give the same numbers.
import type { GameDoc } from '@/core';
import { DAY_MS, IST_OFFSET_MS } from '../admin/time';
import type { CleanBatch, PropValue } from './events';
import type {
  AdminDevice, AdminEvent, AdminIp, AdminParticipation, BreakdownDim, BreakdownQuery, BreakdownRow, CohortRow, DeviceListQuery,
  EraseResult, EventFilter, EventListQuery, FunnelQuery, FunnelStep, InsightsData, ParticipationDim, ParticipationRow,
  RequestContext, RetentionStats, ReturnRate, StoredDevice, StoredEvent, StoredParticipation, TrafficTotals,
} from './types';
import { ERASED_NAME } from './types';

export const shortId = (hash: string): string => hash.slice(0, 8);
export const newInsightsData = (): InsightsData => ({ devices: [], ips: [], events: [], participations: [], audit: [], nextEventId: 1, nextAuditId: 1 });

/** Most rows a breakdown returns. */
export const BREAKDOWN_MAX = 3000;
export const BREAKDOWN_DEFAULT = 500;
export const EVENT_LIST_MAX = 200;
export const GAME_EVENTS_MAX = 500;
export const COHORT_WEEKS = 8;

// ---------------------------------------------------------------- India calendar helpers (same arithmetic as the SQL)

/** Days since 1970-01-01 of the India calendar day that contains `ms`. */
export const istDayIndex = (ms: number): number => Math.floor((ms + IST_OFFSET_MS) / DAY_MS);
/** Monday-based week number of an India day index (1970-01-01 was a Thursday). */
export const weekIndex = (day: number): number => Math.floor((day + 3) / 7);
const two = (n: number): string => String(n).padStart(2, '0');
export function dayLabel(day: number): string {
  const d = new Date(day * DAY_MS);
  return `${d.getUTCFullYear()}-${two(d.getUTCMonth() + 1)}-${two(d.getUTCDate())}`;
}

// ---------------------------------------------------------------- writes

function touchDevice(data: InsightsData, ctx: RequestContext): StoredDevice | null {
  if (!ctx.tokenHash) return null;
  let d = data.devices.find((x) => x.tokenHash === ctx.tokenHash);
  if (!d) {
    d = {
      tokenHash: ctx.tokenHash, firstSeen: ctx.at, lastSeen: ctx.at, sessions: 0,
      ip: null, country: null, region: null, city: null, lat: null, lon: null, timezone: null, postal: null,
      deviceType: null, os: null, osVersion: null, browser: null, browserVersion: null, inApp: null, ua: null, language: null,
      screenW: null, screenH: null, viewportW: null, viewportH: null, dpr: null, clientTz: null, touch: null, connection: null, standalone: null,
      firstReferrer: null, firstUtmSource: null, firstUtmMedium: null, firstUtmCampaign: null, firstLanding: null, firstSource: null,
      gamesHosted: 0, gamesJoined: 0, prizesWon: 0, amountWon: 0, lastName: null,
    };
    data.devices.push(d);
  }
  d.firstSeen = Math.min(d.firstSeen, ctx.at);
  d.lastSeen = Math.max(d.lastSeen, ctx.at);
  if (ctx.ip) {
    // The address and the place derived from it always move together.
    Object.assign(d, { ip: ctx.ip, country: ctx.country, region: ctx.region, city: ctx.city, lat: ctx.lat, lon: ctx.lon, timezone: ctx.timezone, postal: ctx.postal });
    const seen = data.ips.find((x) => x.tokenHash === ctx.tokenHash && x.ip === ctx.ip);
    if (seen) Object.assign(seen, { lastSeen: Math.max(seen.lastSeen, ctx.at), hits: seen.hits + 1, country: ctx.country, region: ctx.region, city: ctx.city });
    else data.ips.push({ tokenHash: ctx.tokenHash, ip: ctx.ip, country: ctx.country, region: ctx.region, city: ctx.city, firstSeen: ctx.at, lastSeen: ctx.at, hits: 1 });
  }
  if (ctx.ua) Object.assign(d, { deviceType: ctx.deviceType, os: ctx.os, osVersion: ctx.osVersion, browser: ctx.browser, browserVersion: ctx.browserVersion, inApp: ctx.inApp, ua: ctx.ua });
  if (ctx.language) d.language = ctx.language;
  return d;
}

const num = (v: PropValue | undefined): number | null => (typeof v === 'number' ? v : null);
const txt = (v: PropValue | undefined): string | null => (typeof v === 'string' ? v : null);
const flag = (v: PropValue | undefined): boolean | null => (typeof v === 'boolean' ? v : null);

/** One accepted POST /api/t: remember the device (when it sent a token) and append its events. */
export function applyTrack(data: InsightsData, ctx: RequestContext, batch: CleanBatch): void {
  const d = touchDevice(data, ctx);
  for (const e of batch.events) {
    if (d && e.name === 'session_start') {
      d.sessions += 1;
      const p = e.props;
      d.screenW = num(p.sw) ?? d.screenW; d.screenH = num(p.sh) ?? d.screenH;
      d.viewportW = num(p.vw) ?? d.viewportW; d.viewportH = num(p.vh) ?? d.viewportH;
      d.dpr = num(p.dpr) ?? d.dpr; d.clientTz = txt(p.tz) ?? d.clientTz;
      d.touch = flag(p.touch) ?? d.touch; d.connection = txt(p.conn) ?? d.connection; d.standalone = flag(p.pwa) ?? d.standalone;
      if (d.firstSource === null) {
        d.firstReferrer = txt(p.ref); d.firstUtmSource = txt(p.utm_source); d.firstUtmMedium = txt(p.utm_medium);
        d.firstUtmCampaign = txt(p.utm_campaign); d.firstLanding = txt(p.landing); d.firstSource = batch.source;
      }
    }
    data.events.push({
      id: data.nextEventId++, at: e.at, device: ctx.tokenHash, session: batch.session, name: e.name, code: e.code, path: e.path, props: e.props,
      country: ctx.country, region: ctx.region, city: ctx.city, deviceType: ctx.deviceType, os: ctx.os, browser: ctx.browser, inApp: ctx.inApp, source: batch.source,
    });
  }
}

/** A game was created (role host) or joined (role player) from this request. Counted once per device per game. */
export function applyParticipation(data: InsightsData, ctx: RequestContext, p: { code: string; role: 'host' | 'player'; pid: string | null; name: string }): void {
  const d = touchDevice(data, ctx);
  if (!d || !ctx.tokenHash) return;
  if (data.participations.some((x) => x.code === p.code && x.tokenHash === ctx.tokenHash)) return;
  data.participations.push({
    code: p.code, tokenHash: ctx.tokenHash, role: p.role, pid: p.pid, at: ctx.at, ip: ctx.ip, country: ctx.country, region: ctx.region, city: ctx.city,
    deviceType: ctx.deviceType, os: ctx.os, osVersion: ctx.osVersion, browser: ctx.browser, browserVersion: ctx.browserVersion, inApp: ctx.inApp,
  });
  if (p.role === 'host') d.gamesHosted += 1;
  else d.gamesJoined += 1;
  d.lastName = p.name.slice(0, 40);
}

export function applyWin(data: InsightsData, tokenHash: string, amount: number): void {
  const d = data.devices.find((x) => x.tokenHash === tokenHash);
  if (!d) return;
  d.prizesWon += 1;
  d.amountWon += Math.max(0, Math.floor(amount) || 0);
}

/** Retention: drop everything last touched before `cutoff`. Returns how many rows went. */
export function purgeInsights(data: InsightsData, cutoff: number): number {
  const before = data.events.length + data.devices.length + data.ips.length + data.participations.length;
  data.events = data.events.filter((e) => e.at >= cutoff);
  data.devices = data.devices.filter((d) => d.lastSeen >= cutoff);
  data.ips = data.ips.filter((i) => i.lastSeen >= cutoff);
  data.participations = data.participations.filter((p) => p.at >= cutoff);
  return before - (data.events.length + data.devices.length + data.ips.length + data.participations.length);
}

/** Erase a device from the insights rows (the game documents are handled by the store). Counts what was removed. */
export function eraseFromInsights(data: InsightsData, id: string): Pick<EraseResult, 'devices' | 'ips' | 'events' | 'participations'> {
  const is = (hash: string | null): boolean => !!hash && shortId(hash) === id;
  const out = {
    devices: data.devices.filter((d) => is(d.tokenHash)).length,
    ips: data.ips.filter((i) => is(i.tokenHash)).length,
    events: data.events.filter((e) => is(e.device)).length,
    participations: data.participations.filter((p) => is(p.tokenHash)).length,
  };
  data.devices = data.devices.filter((d) => !is(d.tokenHash));
  data.ips = data.ips.filter((i) => !is(i.tokenHash));
  data.events = data.events.filter((e) => !is(e.device));
  data.participations = data.participations.filter((p) => !is(p.tokenHash));
  return out;
}

/** Replace every name this device typed in a game document. `pids` = its seats; `isHost` = it created the game. */
export function anonymiseDoc(doc: GameDoc, pids: readonly string[], isHost: boolean): GameDoc {
  const mine = (pid: unknown): boolean => typeof pid === 'string' && pids.includes(pid);
  const prizes = (list: GameDoc['prizes'] | undefined): GameDoc['prizes'] =>
    (list ?? []).map((p) => (mine(p.winnerPid) ? { ...p, winnerName: ERASED_NAME } : p));
  return {
    ...doc,
    ...(isHost ? { hostName: ERASED_NAME } : {}),
    players: (doc.players ?? []).map((p) => (mine(p.pid) ? { ...p, name: ERASED_NAME } : p)),
    prizes: prizes(doc.prizes),
    events: (doc.events ?? []).map((e) => ('pid' in e && mine(e.pid) ? { ...e, name: ERASED_NAME } : e)),
    ...(doc.history ? { history: doc.history.map((r) => ({ ...r, prizes: prizes(r.prizes) })) } : {}),
  };
}

// ---------------------------------------------------------------- reads: events

function matches(e: StoredEvent, f: EventFilter): boolean {
  return e.at >= f.from && e.at < f.to
    && (!f.names || f.names.includes(e.name))
    && (!f.deviceType || e.deviceType === f.deviceType)
    && (!f.source || e.source === f.source)
    && (!f.code || e.code === f.code);
}

const prop = (e: StoredEvent, key: string): string => {
  const v = e.props[key];
  return v === undefined || v === null ? '' : String(v);
};

/** The funnel "step" an event is: its name, with the page for page views and the role for results. */
export function stepKey(e: Pick<StoredEvent, 'name' | 'props'>): string {
  if (e.name === 'page_view') return `page_view:${e.props.page ?? ''}`;
  if (e.name === 'results_seen') return `results_seen:${e.props.role ?? ''}`;
  return e.name;
}

export function screenBucket(sw: unknown): string {
  if (typeof sw !== 'number') return '';
  if (sw < 360) return '0-359';
  if (sw < 480) return '360-479';
  if (sw < 768) return '480-767';
  if (sw < 1024) return '768-1023';
  if (sw < 1440) return '1024-1439';
  return '1440+';
}

export function dimKey(e: StoredEvent, dim: BreakdownDim): string {
  switch (dim) {
    case 'all': return 'all';
    case 'name': return e.name;
    case 'step': return stepKey(e);
    case 'day': return dayLabel(istDayIndex(e.at));
    case 'hourdow': {
      const day = istDayIndex(e.at);
      const dow = (((day + 3) % 7) + 7) % 7; // 0 = Monday
      return `${dow}-${two(new Date(e.at + IST_OFFSET_MS).getUTCHours())}`;
    }
    case 'country': return e.country ?? '';
    case 'region': return e.country && e.region ? `${e.country}-${e.region}` : '';
    case 'city': return e.city ? `${e.city}|${e.region ?? ''}|${e.country ?? ''}` : '';
    case 'device_type': return e.deviceType ?? '';
    case 'os': return e.os ?? '';
    case 'browser': return e.browser ?? '';
    case 'in_app': return e.inApp ?? '';
    case 'source': return e.source ?? '';
    case 'path': return e.path ?? '';
    case 'code': return e.code ?? '';
    case 'screen': return screenBucket(e.props.sw);
    default: {
      if (!dim.startsWith('prop:')) return '';
      // "prop:a+b" pairs two properties: "top:23".
      const [a, b] = dim.slice(5).split('+');
      return b === undefined ? prop(e, a) : `${prop(e, a)}:${prop(e, b)}`;
    }
  }
}

const actor = (e: StoredEvent): string => e.device ?? `s:${e.session}`;
const cmp = (a: string, b: string): number => (a < b ? -1 : a > b ? 1 : 0);

export function eventBreakdown(events: readonly StoredEvent[], q: BreakdownQuery): BreakdownRow[] {
  const groups = new Map<string, { events: number; sessions: Set<string>; devices: Set<string> }>();
  for (const e of events) {
    if (!matches(e, q)) continue;
    const key = dimKey(e, q.dim);
    let g = groups.get(key);
    if (!g) groups.set(key, (g = { events: 0, sessions: new Set(), devices: new Set() }));
    g.events += 1;
    g.sessions.add(e.session);
    g.devices.add(actor(e));
  }
  return [...groups]
    .map(([key, g]) => ({ key, events: g.events, sessions: g.sessions.size, devices: g.devices.size }))
    .sort((a, b) => b.devices - a.devices || b.events - a.events || cmp(a.key, b.key))
    .slice(0, Math.min(Math.max(1, q.limit ?? BREAKDOWN_DEFAULT), BREAKDOWN_MAX));
}

export function funnel(events: readonly StoredEvent[], q: FunnelQuery): FunnelStep[] {
  const done = new Map<string, Set<string>>();
  for (const e of events) {
    if (!matches(e, q)) continue;
    const step = stepKey(e);
    if (!q.steps.includes(step)) continue;
    const a = actor(e);
    let s = done.get(a);
    if (!s) done.set(a, (s = new Set()));
    s.add(step);
  }
  return q.steps.map((step, i) => {
    let any = 0, kept = 0;
    for (const s of done.values()) {
      if (s.has(step)) any++;
      if (q.steps.slice(0, i + 1).every((x) => s.has(x))) kept++;
    }
    return { step, any, kept };
  });
}

export function trafficTotals(data: Pick<InsightsData, 'events' | 'devices'>, from: number, to: number): TrafficTotals {
  const sessions = new Map<string, number | null>();
  const actors = new Set<string>();
  const devices = new Set<string>();
  let events = 0, pageViews = 0;
  for (const e of data.events) {
    if (e.at < from || e.at >= to) continue;
    events++;
    if (e.name === 'page_view') pageViews++;
    actors.add(actor(e));
    if (e.device) devices.add(e.device);
    const ms = e.name === 'session_end' && typeof e.props.ms === 'number' ? e.props.ms : null;
    const cur = sessions.get(e.session);
    sessions.set(e.session, ms === null ? cur ?? null : Math.max(cur ?? 0, ms));
  }
  const firstSeen = new Map(data.devices.map((d) => [d.tokenHash, d.firstSeen]));
  let returningDevices = 0, timedSessions = 0, sessionMs = 0;
  for (const d of devices) if ((firstSeen.get(d) ?? Infinity) < from) returningDevices++;
  for (const ms of sessions.values()) if (ms !== null) { timedSessions++; sessionMs += ms; }
  return {
    visitors: actors.size, sessions: sessions.size, events, pageViews,
    newDevices: data.devices.filter((d) => d.firstSeen >= from && d.firstSeen < to).length,
    returningDevices, timedSessions, sessionMs,
  };
}

export function listEvents(events: readonly StoredEvent[], q: EventListQuery): { total: number; rows: AdminEvent[] } {
  const rows = events.filter((e) =>
    (q.from === undefined || e.at >= q.from) && (q.to === undefined || e.at < q.to)
    && (!q.name || e.name === q.name) && (!q.device || (!!e.device && shortId(e.device) === q.device))
    && (!q.code || e.code === q.code) && (!q.session || e.session === q.session));
  rows.sort((a, b) => b.at - a.at || b.id - a.id);
  const limit = Math.min(EVENT_LIST_MAX, Math.max(1, Math.floor(q.limit)));
  const offset = Math.max(0, Math.floor(q.offset));
  return { total: rows.length, rows: rows.slice(offset, offset + limit).map(adminEvent) };
}

export const adminEvent = (e: StoredEvent): AdminEvent => ({ ...e, props: { ...e.props }, device: e.device ? shortId(e.device) : null });

// ---------------------------------------------------------------- reads: participations

function partKey(p: StoredParticipation, dim: ParticipationDim): string {
  switch (dim) {
    case 'country': return p.country ?? '';
    case 'region': return p.country && p.region ? `${p.country}-${p.region}` : '';
    case 'city': return p.city ? `${p.city}|${p.region ?? ''}|${p.country ?? ''}` : '';
    case 'device_type': return p.deviceType ?? '';
    case 'os': return p.os ?? '';
    case 'browser': return p.browser ?? '';
  }
}

export function participationBreakdown(parts: readonly StoredParticipation[], from: number, to: number, dim: ParticipationDim): ParticipationRow[] {
  const groups = new Map<string, { games: number; players: number; devices: Set<string> }>();
  for (const p of parts) {
    if (p.at < from || p.at >= to) continue;
    const key = partKey(p, dim);
    let g = groups.get(key);
    if (!g) groups.set(key, (g = { games: 0, players: 0, devices: new Set() }));
    if (p.role === 'host') g.games += 1;
    if (p.pid) g.players += 1;
    g.devices.add(p.tokenHash);
  }
  return [...groups]
    .map(([key, g]) => ({ key, games: g.games, players: g.players, devices: g.devices.size }))
    .sort((a, b) => b.devices - a.devices || b.players - a.players || b.games - a.games || cmp(a.key, b.key))
    .slice(0, BREAKDOWN_DEFAULT);
}

export function adminParticipation(p: StoredParticipation, devices: readonly StoredDevice[]): AdminParticipation {
  const { tokenHash, ...rest } = p;
  return { ...rest, device: shortId(tokenHash), source: devices.find((d) => d.tokenHash === tokenHash)?.firstSource ?? null };
}

/** code → the host's participation, for the plays table. */
export function gameHosts(data: Pick<InsightsData, 'participations' | 'devices'>, codes: readonly string[]): Record<string, AdminParticipation> {
  const out: Record<string, AdminParticipation> = {};
  for (const p of data.participations) if (p.role === 'host' && codes.includes(p.code)) out[p.code] = adminParticipation(p, data.devices);
  return out;
}

// ---------------------------------------------------------------- reads: retention

export function retention(data: Pick<InsightsData, 'events' | 'devices' | 'participations'>, now: number, weeks: number = COHORT_WEEKS): RetentionStats {
  const today = istDayIndex(now);
  // Every India day each device was active on (had at least one event).
  const activeDays = new Map<string, Set<number>>();
  for (const e of data.events) {
    if (!e.device) continue;
    let s = activeDays.get(e.device);
    if (!s) activeDays.set(e.device, (s = new Set()));
    s.add(istDayIndex(e.at));
  }

  const thisWeek = weekIndex(today);
  const cohorts: CohortRow[] = [];
  for (let w = thisWeek - weeks + 1; w <= thisWeek; w++) {
    const members = data.devices.filter((d) => weekIndex(istDayIndex(d.firstSeen)) === w);
    const active = Array.from({ length: thisWeek - w + 1 }, (_, k) =>
      members.filter((d) => [...(activeDays.get(d.tokenHash) ?? [])].some((day) => weekIndex(day) === w + k)).length);
    cohorts.push({ week: dayLabel(w * 7 - 3), size: members.length, active });
  }

  const rate = (n: number): ReturnRate => {
    let eligible = 0, returned = 0;
    for (const d of data.devices) {
      const first = istDayIndex(d.firstSeen);
      if (first > today - n) continue;
      eligible++;
      if ([...(activeDays.get(d.tokenHash) ?? [])].some((day) => day >= first + n)) returned++;
    }
    return { eligible, returned };
  };

  const hostDays = new Map<string, Set<number>>();
  for (const p of data.participations) {
    if (p.role !== 'host') continue;
    let s = hostDays.get(p.tokenHash);
    if (!s) hostDays.set(p.tokenHash, (s = new Set()));
    s.add(istDayIndex(p.at));
  }
  return {
    cohorts, d1: rate(1), d7: rate(7), d30: rate(30),
    hosts: hostDays.size, returningHosts: [...hostDays.values()].filter((s) => s.size >= 2).length,
  };
}

// ---------------------------------------------------------------- reads: devices

export const adminDevice = (d: StoredDevice): AdminDevice => {
  const { tokenHash, ...rest } = d;
  return { ...rest, id: shortId(tokenHash) };
};

export function listDevices(devices: readonly StoredDevice[], q: DeviceListQuery): { total: number; rows: AdminDevice[] } {
  const s = q.search?.trim().toLowerCase();
  const key = (d: StoredDevice): number => {
    switch (q.sort) {
      case 'firstSeen': return d.firstSeen;
      case 'sessions': return d.sessions;
      case 'hosted': return d.gamesHosted;
      case 'joined': return d.gamesJoined;
      case 'won': return d.prizesWon;
      case 'amount': return d.amountWon;
      default: return d.lastSeen;
    }
  };
  const sign = q.dir === 'asc' ? 1 : -1;
  const rows = devices
    .filter((d) => (!q.played || d.gamesHosted + d.gamesJoined > 0)
      && (!s || shortId(d.tokenHash).includes(s) || (d.lastName ?? '').toLowerCase().includes(s) || (d.city ?? '').toLowerCase().includes(s) || (d.ip ?? '').includes(s)))
    .sort((a, b) => sign * (key(a) - key(b)) || cmp(a.tokenHash, b.tokenHash));
  const limit = Math.min(100, Math.max(1, Math.floor(q.limit)));
  const offset = Math.max(0, Math.floor(q.offset));
  return { total: rows.length, rows: rows.slice(offset, offset + limit).map(adminDevice) };
}

export function getDevice(data: Pick<InsightsData, 'devices' | 'ips'>, id: string): { device: AdminDevice; ips: AdminIp[] } | null {
  const d = data.devices.find((x) => shortId(x.tokenHash) === id);
  if (!d) return null;
  const ips = data.ips.filter((i) => i.tokenHash === d.tokenHash).sort((a, b) => b.lastSeen - a.lastSeen || cmp(a.ip, b.ip))
    .map((i): AdminIp => ({ ip: i.ip, country: i.country, region: i.region, city: i.city, firstSeen: i.firstSeen, lastSeen: i.lastSeen, hits: i.hits }));
  return { device: adminDevice(d), ips };
}
